#!/usr/bin/env node
// Renders the architecture diagram from docs/architecture.model.json. No dependencies.
//
//   node scripts/render-architecture.mjs           write the files
//   node scripts/render-architecture.mjs --check   exit 1 if a generated file is out of date
//
// Outputs:
//   docs/architecture.svg      the image the README embeds (plain SVG, simplified service tiles)
//   docs/architecture.drawio   the same diagram with draw.io's built-in AWS shapes (editable)
//   the Mermaid block in docs/architecture.md, between the BEGIN/END MERMAID markers
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const MODEL = join(ROOT, "docs", "architecture.model.json");
const OUT_SVG = join(ROOT, "docs", "architecture.svg");
const OUT_DRAWIO = join(ROOT, "docs", "architecture.drawio");
const OUT_MD = join(ROOT, "docs", "architecture.md");
const MD_BEGIN = "<!-- BEGIN MERMAID (generated by scripts/render-architecture.mjs, do not edit) -->";
const MD_END = "<!-- END MERMAID -->";
const STEPS_BEGIN = "<!-- BEGIN STEPS (generated by scripts/render-architecture.mjs, do not edit) -->";
const STEPS_END = "<!-- END STEPS -->";

// AWS category colours.
const COLOR = {
  compute: "#ED7100",
  network: "#8C4FFF",
  storage: "#7AA116",
  ml: "#01A88D",
  security: "#DD344C",
  mgmt: "#E7157B",
  generic: "#5A6C86",
};
// service -> tile look (SVG) and draw.io shape
const SERVICES = {
  mixer: { cat: "generic", band: "Venue", glyph: "MIX", drawio: { std: "traditional_server" } },
  obs: { cat: "generic", band: "Encoder", glyph: "OBS", drawio: { std: "client" } },
  browser: { cat: "generic", band: "Client", glyph: "WWW", drawio: { std: "mobile_client" } },
  fargate: { cat: "compute", band: "Compute", glyph: "FG", drawio: { res: "fargate" } },
  ec2: { cat: "compute", band: "Compute", glyph: "EC2", drawio: { res: "ec2" } },
  lambda: { cat: "compute", band: "Compute", glyph: "λ", drawio: { res: "lambda" } },
  eip: { cat: "compute", band: "EC2", glyph: "EIP", drawio: { std: "elastic_ip_address", w: 48, h: 20 } },
  nlb: { cat: "network", band: "Networking", glyph: "NLB", drawio: { std: "network_load_balancer" } },
  cloudfront: { cat: "network", band: "Networking", glyph: "CF", drawio: { res: "cloudfront" } },
  s3: { cat: "storage", band: "Storage", glyph: "S3", drawio: { res: "s3" } },
  transcribe: { cat: "ml", band: "AI/ML", glyph: "TR", drawio: { res: "transcribe" } },
  translate: { cat: "ml", band: "AI/ML", glyph: "TL", drawio: { res: "translate" } },
  bedrock: { cat: "ml", band: "AI/ML", glyph: "BR", drawio: { res: "bedrock" } },
  polly: { cat: "ml", band: "AI/ML", glyph: "PO", drawio: { res: "polly" } },
  secrets: { cat: "security", band: "Security", glyph: "SM", drawio: { res: "secrets_manager" } },
  cloudwatch: { cat: "mgmt", band: "Management", glyph: "CW", drawio: { res: "cloudwatch_2" } },
};
const GROUP_STYLE = {
  aws: { stroke: "#232F3E", fill: "none", dash: "", label: "#232F3E", gr: "group_aws_cloud_alt" },
  vpc: { stroke: "#8C4FFF", fill: "none", dash: "", label: "#6B34D6", gr: "group_vpc2" },
  service: { stroke: "#7D8998", fill: "none", dash: "6 4", label: "#4A5565", gr: null },
  venue: { stroke: "#7D8998", fill: "none", dash: "", label: "#4A5565", gr: "group_corporate_data_center" },
};
const TILE_W = 84;
const TILE_H = 60;
const FONT = "system-ui, -apple-system, 'Segoe UI', Arial, sans-serif";
const INK = "#232F3E";

export function loadModel(path = MODEL) {
  return JSON.parse(readFileSync(path, "utf8"));
}

const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const lines = (s) => String(s).split("\n");
const textW = (s, px = 12) => Math.ceil(Math.max(...lines(s).map((l) => l.length)) * px * 0.56);

/** Bounding box of a node: the tile plus its name under it. */
function bbox(n) {
  const w = Math.max(TILE_W, textW(n.label) + 8);
  const h = TILE_H + 8 + 15 * lines(n.label).length;
  return { x: n.cx - w / 2, y: n.cy - TILE_H / 2, w, h };
}

/** Where the segment from a (inside box b) to p leaves b (with a small margin). */
function leave(b, a, p, margin = 4) {
  const x0 = b.x - margin, x1 = b.x + b.w + margin, y0 = b.y - margin, y1 = b.y + b.h + margin;
  const dx = p.x - a.x, dy = p.y - a.y;
  let t = Infinity;
  if (dx > 0) t = Math.min(t, (x1 - a.x) / dx);
  if (dx < 0) t = Math.min(t, (x0 - a.x) / dx);
  if (dy > 0) t = Math.min(t, (y1 - a.y) / dy);
  if (dy < 0) t = Math.min(t, (y0 - a.y) / dy);
  t = Math.min(t, 1);
  return { x: a.x + dx * t, y: a.y + dy * t };
}

export function layoutEdges(model) {
  const byId = new Map(model.nodes.map((n) => [n.id, n]));
  return model.edges.map((e) => {
    const A = byId.get(e.from), B = byId.get(e.to);
    const ba = bbox(A), bb = bbox(B);
    const ca = { x: ba.x + ba.w / 2, y: ba.y + ba.h / 2 };
    const cb = { x: bb.x + bb.w / 2, y: bb.y + bb.h / 2 };
    const len = Math.hypot(cb.x - ca.x, cb.y - ca.y) || 1;
    const nx = -(cb.y - ca.y) / len, ny = (cb.x - ca.x) / len;
    const off = e.offset || 0;
    const a = { x: ca.x + nx * off, y: ca.y + ny * off };
    const b = { x: cb.x + nx * off, y: cb.y + ny * off };
    const p1 = leave(ba, a, b);
    const p2 = leave(bb, b, a);
    const t = e.t ?? 0.5;
    return { ...e, p1, p2, mid: { x: p1.x + (p2.x - p1.x) * t, y: p1.y + (p2.y - p1.y) * t } };
  });
}

export function stepLabel(e) {
  return e.step ?? e.variantOf ?? null;
}

// ------------------------------------------------------------------ SVG
function tileSvg(n) {
  const s = SERVICES[n.service];
  const col = COLOR[s.cat];
  const x = n.cx - TILE_W / 2, y = n.cy - TILE_H / 2;
  const out = [];
  out.push(`<g id="node-${n.id}">`);
  out.push(`<rect x="${x}" y="${y}" width="${TILE_W}" height="${TILE_H}" rx="8" fill="#FFFFFF" stroke="${col}" stroke-width="2"/>`);
  out.push(`<path d="M${x} ${y + 18} V${y + 8} a8 8 0 0 1 8 -8 H${x + TILE_W - 8} a8 8 0 0 1 8 8 V${y + 18} Z" fill="${col}"/>`);
  out.push(`<text x="${n.cx}" y="${y + 13}" text-anchor="middle" font-size="10" font-weight="700" fill="#FFFFFF">${esc(s.band)}</text>`);
  out.push(`<text x="${n.cx}" y="${y + 47}" text-anchor="middle" font-size="${s.glyph.length > 2 ? 19 : 22}" font-weight="700" fill="${col}">${esc(s.glyph)}</text>`);
  lines(n.label).forEach((l, i) => {
    out.push(`<text x="${n.cx}" y="${y + TILE_H + 16 + i * 15}" text-anchor="middle" font-size="12" fill="${INK}">${esc(l)}</text>`);
  });
  out.push("</g>");
  return out.join("\n");
}

export function renderSvg(model) {
  const edges = layoutEdges(model);
  const W = model.width, H = model.height;
  const o = [];
  o.push(`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" font-family="${FONT}" role="img" aria-labelledby="title desc">`);
  o.push(`<title id="title">${esc(model.title)}</title>`);
  o.push(`<desc id="desc">${esc(model.desc)}</desc>`);
  o.push(`<defs>`);
  o.push(`<marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 z" fill="${INK}"/></marker>`);
  o.push(`<marker id="arrow-light" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 z" fill="#8896A5"/></marker>`);
  o.push(`</defs>`);
  o.push(`<rect width="${W}" height="${H}" fill="#FFFFFF"/>`);
  o.push(`<text x="20" y="38" font-size="22" font-weight="700" fill="${INK}">${esc(model.title)}</text>`);
  // groups (parents first, as listed)
  for (const g of model.groups) {
    const st = GROUP_STYLE[g.kind];
    o.push(`<g id="group-${g.id}">`);
    o.push(`<rect x="${g.x}" y="${g.y}" width="${g.w}" height="${g.h}" rx="6" fill="${st.fill}" stroke="${st.stroke}" stroke-width="1.5"${st.dash ? ` stroke-dasharray="${st.dash}"` : ""}/>`);
    o.push(`<text x="${g.x + 12}" y="${g.y + 20}" font-size="13" font-weight="700" fill="${st.label}">${esc(g.label)}</text>`);
    if (g.sublabel) o.push(`<text x="${g.x + 12}" y="${g.y + 36}" font-size="11" fill="#5A6C86">${esc(g.sublabel)}</text>`);
    o.push("</g>");
  }
  for (const n of model.notes || []) {
    o.push(`<text x="${n.x}" y="${n.y}" text-anchor="${n.anchor || "start"}" font-size="11" font-style="italic" fill="#5A6C86">${esc(n.text)}</text>`);
  }
  // edges below tiles
  const flow = [], marks = [];
  for (const e of edges) {
    const light = e.style === "support" || e.style === "assoc";
    const dash = e.style === "support" ? ` stroke-dasharray="5 4"` : e.style === "assoc" ? ` stroke-dasharray="2 3"` : e.optional ? ` stroke-dasharray="7 4"` : "";
    const marker = e.style === "assoc" ? "" : ` marker-end="url(#${light ? "arrow-light" : "arrow"})"`;
    flow.push(`<line id="edge-${e.id}" x1="${e.p1.x.toFixed(1)}" y1="${e.p1.y.toFixed(1)}" x2="${e.p2.x.toFixed(1)}" y2="${e.p2.y.toFixed(1)}" stroke="${light ? "#8896A5" : INK}" stroke-width="${light ? 1.4 : 2}"${dash}${marker}/>`);
    const sl = stepLabel(e);
    if (sl !== null && !e.variantOf) {
      marks.push(`<g id="step-${e.id}"><circle cx="${e.mid.x.toFixed(1)}" cy="${e.mid.y.toFixed(1)}" r="11" fill="${INK}" stroke="#FFFFFF" stroke-width="2"/><text x="${e.mid.x.toFixed(1)}" y="${(e.mid.y + 4.2).toFixed(1)}" text-anchor="middle" font-size="12" font-weight="700" fill="#FFFFFF">${sl}</text></g>`);
    }
  }
  o.push(...flow);
  for (const n of model.nodes) o.push(tileSvg(n));
  o.push(...marks);
  // legend
  const LY = model.groups.reduce((m, g) => Math.max(m, g.y + g.h), 0) + 22;
  const steps = model.edges.filter((e) => e.step).sort((a, b) => a.step - b.step);
  const rows = Math.ceil(steps.length / 2);
  const LH = 40 + rows * 26 + 34;
  o.push(`<g id="legend">`);
  o.push(`<rect x="20" y="${LY}" width="${W - 40}" height="${LH}" rx="6" fill="#F7F8FA" stroke="#C7CFD8"/>`);
  o.push(`<text x="32" y="${LY + 24}" font-size="13" font-weight="700" fill="${INK}">Legend: numbered flow</text>`);
  steps.forEach((e, i) => {
    const col = i < rows ? 0 : 1;
    const r = i % rows;
    const x = 32 + col * 670, y = LY + 52 + r * 26;
    o.push(`<circle cx="${x + 11}" cy="${y - 4}" r="11" fill="${INK}"/><text x="${x + 11}" y="${y + 0.2}" text-anchor="middle" font-size="12" font-weight="700" fill="#FFFFFF">${e.step}</text>`);
    o.push(`<text x="${x + 30}" y="${y}" font-size="12.5" fill="${INK}">${esc(e.text)}</text>`);
  });
  o.push(`<text x="32" y="${LY + 52 + rows * 26 + 4}" font-size="12" fill="#4A5565">${esc(model.legendNote)}</text>`);
  o.push("</g>");
  o.push(`<text x="20" y="${H - 14}" font-size="11" fill="#5A6C86">${esc(model.footer)}</text>`);
  o.push("</svg>");
  return o.join("\n") + "\n";
}

// ------------------------------------------------------------------ draw.io
export function renderDrawio(model) {
  const edges = layoutEdges(model);
  const cells = [];
  const attr = (s) => esc(s).replace(/\n/g, "&#xa;");
  const base = `sketch=0;outlineConnect=0;fontColor=${INK};dashed=0;verticalLabelPosition=bottom;verticalAlign=top;align=center;html=1;fontSize=12;fontStyle=0;aspect=fixed;`;
  cells.push(`<mxCell id="0"/>`);
  cells.push(`<mxCell id="1" parent="0"/>`);
  cells.push(`<mxCell id="title" value="${attr(model.title)}" style="text;html=1;align=left;verticalAlign=middle;fontSize=22;fontStyle=1;fontColor=${INK};" vertex="1" parent="1"><mxGeometry x="20" y="16" width="800" height="32" as="geometry"/></mxCell>`);
  for (const g of model.groups) {
    const st = GROUP_STYLE[g.kind];
    const shape = st.gr
      ? `shape=mxgraph.aws4.group;grIcon=mxgraph.aws4.${st.gr};`
      : `shape=rect;rounded=1;arcSize=2;`;
    const style = `${shape}strokeColor=${st.stroke};fillColor=none;verticalAlign=top;align=left;spacingLeft=30;fontColor=${st.label};fontStyle=1;html=1;${st.dash ? "dashed=1;" : "dashed=0;"}`;
    const label = g.sublabel ? `${g.label}<br><font style="font-size:11px;font-weight:normal">${g.sublabel}</font>` : g.label;
    cells.push(`<mxCell id="g_${g.id}" value="${esc(label)}" style="${style}" vertex="1" parent="1"><mxGeometry x="${g.x}" y="${g.y}" width="${g.w}" height="${g.h}" as="geometry"/></mxCell>`);
  }
  (model.notes || []).forEach((n, i) => {
    cells.push(`<mxCell id="note_${i}" value="${esc(n.text)}" style="text;html=1;align=center;verticalAlign=middle;fontSize=11;fontStyle=2;fontColor=#5A6C86;" vertex="1" parent="1"><mxGeometry x="${n.x - 40}" y="${n.y - 14}" width="80" height="20" as="geometry"/></mxCell>`);
  });
  for (const n of model.nodes) {
    const s = SERVICES[n.service];
    const d = s.drawio;
    const col = COLOR[s.cat];
    const w = d.w ?? 60, h = d.h ?? 60;
    const label = lines(n.label).map(esc).join("<br>");
    let style;
    if (d.res) style = `${base}fillColor=${col};strokeColor=#ffffff;gradientColor=none;shape=mxgraph.aws4.resourceIcon;resIcon=mxgraph.aws4.${d.res};`;
    else style = `${base}fillColor=${col};strokeColor=none;gradientColor=none;shape=mxgraph.aws4.${d.std};`;
    cells.push(`<mxCell id="n_${n.id}" value="${esc(label)}" style="${style}" vertex="1" parent="1"><mxGeometry x="${n.cx - w / 2}" y="${n.cy - h / 2}" width="${w}" height="${h}" as="geometry"/></mxCell>`);
  }
  for (const e of edges) {
    const light = e.style === "support" || e.style === "assoc";
    const dash = e.style === "support" ? "dashed=1;dashPattern=5 4;" : e.style === "assoc" ? "dashed=1;dashPattern=2 3;" : e.optional ? "dashed=1;dashPattern=7 4;" : "";
    const sl = stepLabel(e);
    const value = sl !== null && !e.variantOf ? String(sl) : "";
    const style = `edgeStyle=none;html=1;rounded=0;endArrow=${e.style === "assoc" ? "none" : "classic"};strokeWidth=${light ? 1.4 : 2};strokeColor=${light ? "#8896A5" : INK};${dash}fontStyle=1;fontColor=#ffffff;labelBackgroundColor=${INK};labelBorderColor=#ffffff;`;
    cells.push(`<mxCell id="e_${e.id}" value="${value}" style="${style}" edge="1" parent="1" source="n_${e.from}" target="n_${e.to}"><mxGeometry relative="1" as="geometry"/></mxCell>`);
  }
  // legend as one text cell
  const LY = model.groups.reduce((m, g) => Math.max(m, g.y + g.h), 0) + 22;
  const steps = model.edges.filter((e) => e.step).sort((a, b) => a.step - b.step);
  const legend = [`<b>Legend: numbered flow</b>`, ...steps.map((e) => `${e.step}. ${esc(e.text)}`), `<i>${esc(model.legendNote)}</i>`].join("<br>");
  cells.push(`<mxCell id="legend" value="${esc(legend)}" style="text;html=1;align=left;verticalAlign=top;whiteSpace=wrap;fontSize=12;fontColor=${INK};fillColor=#F7F8FA;strokeColor=#C7CFD8;spacing=10;" vertex="1" parent="1"><mxGeometry x="20" y="${LY}" width="${model.width - 40}" height="${30 + steps.length * 18 + 40}" as="geometry"/></mxCell>`);
  cells.push(`<mxCell id="footer" value="${esc(model.footer)}" style="text;html=1;align=left;verticalAlign=middle;fontSize=11;fontColor=#5A6C86;" vertex="1" parent="1"><mxGeometry x="20" y="${model.height - 26}" width="1360" height="20" as="geometry"/></mxCell>`);
  return (
    `<mxfile>\n  <diagram id="architecture" name="Architecture">\n    <mxGraphModel dx="1400" dy="900" grid="0" gridSize="10" guides="1" tooltips="1" connect="1" arrows="1" fold="1" page="1" pageScale="1" pageWidth="${model.width}" pageHeight="${model.height}" math="0" shadow="0">\n      <root>\n` +
    cells.map((c) => "        " + c).join("\n") +
    `\n      </root>\n    </mxGraphModel>\n  </diagram>\n</mxfile>\n`
  );
}

// ------------------------------------------------------------------ Mermaid
export function renderMermaid(model) {
  const q = (s) => `"${String(s).replace(/"/g, "'").replace(/\n/g, "<br/>")}"`;
  const o = ["```mermaid", "flowchart LR"];
  const kids = (pid) => model.groups.filter((g) => (g.parent ?? null) === pid);
  const emitGroup = (g, ind) => {
    o.push(`${ind}subgraph ${g.id}[${q(g.label)}]`);
    for (const n of model.nodes.filter((x) => x.group === g.id)) o.push(`${ind}  ${n.id}[${q(n.label)}]`);
    for (const c of kids(g.id)) emitGroup(c, ind + "  ");
    o.push(`${ind}end`);
  };
  for (const g of kids(null)) emitGroup(g, "  ");
  for (const e of model.edges) {
    const sl = stepLabel(e);
    const arrow = e.style === "support" ? "-.->" : e.style === "assoc" ? "-.-" : e.optional ? "-.->" : "-->";
    const label = sl !== null && !e.variantOf ? `|${sl}|` : "";
    o.push(`  ${e.from} ${arrow}${label} ${e.to}`);
  }
  o.push("```");
  return o.join("\n");
}

export function stepTable(model) {
  const rows = ["| Step | What happens |", "|---|---|"];
  for (const e of model.edges.filter((x) => x.step).sort((a, b) => a.step - b.step)) rows.push(`| ${e.step} | ${e.text} |`);
  return rows.join("\n");
}

function replaceBlock(md, begin, end, body) {
  const a = md.indexOf(begin), b = md.indexOf(end);
  if (a < 0 || b < a) throw new Error(`${OUT_MD} must contain the markers:\n${begin}\n${end}`);
  return md.slice(0, a) + begin + "\n" + body + "\n" + md.slice(b);
}

function mdWithMermaid(model) {
  let md = readFileSync(OUT_MD, "utf8");
  md = replaceBlock(md, MD_BEGIN, MD_END, renderMermaid(model));
  return replaceBlock(md, STEPS_BEGIN, STEPS_END, stepTable(model));
}

export function generate(model) {
  return [
    { path: OUT_SVG, content: renderSvg(model) },
    { path: OUT_DRAWIO, content: renderDrawio(model) },
    { path: OUT_MD, content: mdWithMermaid(model) },
  ];
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes("--check");
  const model = loadModel();
  let stale = 0;
  for (const f of generate(model)) {
    const old = existsSync(f.path) ? readFileSync(f.path, "utf8") : null;
    if (old === f.content) continue;
    if (check) {
      console.error(`out of date: ${f.path.replace(ROOT + "/", "")}`);
      stale++;
    } else {
      writeFileSync(f.path, f.content);
      console.log(`wrote ${f.path.replace(ROOT + "/", "")}`);
    }
  }
  if (check) {
    if (stale) {
      console.error("Run: node scripts/render-architecture.mjs");
      process.exit(1);
    }
    console.log("architecture files are up to date");
  }
}
